using Myriale.Api.Architecture; namespace Myriale.Api.Features.SessionArtifacts; [FeatureSlice("SessionArtifacts")] public static class SessionArtifactsFeature { public static IServiceCollection AddSessionArtifactsFeature(this IServiceCollection s,IConfiguration c){s.AddOptions<SessionImageOptions>().Bind(c.GetSection(SessionImageOptions.SectionName)).Validate(o=>o.MaxBytes>0&&o.MaxWidth>0&&o.MaxHeight>0&&o.ReconciliationIntervalMinutes>0&&o.OrphanGraceMinutes>=0,"Session image limits must be valid.").ValidateOnStart();s.AddScoped<ISessionArtifactWriter,EfSessionArtifactWriter>();s.AddScoped<EfSessionArtifactRepository>();s.AddScoped<ISessionArtifactRepository>(p=>p.GetRequiredService<EfSessionArtifactRepository>());s.AddScoped<ISessionArtifactRetentionRepository>(p=>p.GetRequiredService<EfSessionArtifactRepository>());s.AddScoped<AttachSessionImageUseCase>();s.AddScoped<GetSessionImageMediaQuery>();s.AddScoped<GetSessionArtifactActivityQuery>();s.AddSingleton<ISessionObjectStorage,FileSessionObjectStorage>();s.AddSingleton<SessionImageValidator>();s.AddScoped<SessionArtifactReconciler>();s.AddHostedService<SessionArtifactRetentionWorker>();return s;} public static IEndpointRouteBuilder MapSessionArtifactsFeature(this IEndpointRouteBuilder e){e.MapSessionArtifactEndpoints();return e;} }
